HARNESS = """
const FIXTURE = %s;
const NODE_JS = %s;
const GATE = %s;

const wrap = (json) => ({ json, first: () => ({ json }) });
const $ = (name) => {
  if (!(name in FIXTURE.nodes)) throw new Error('unmocked node: ' + name);
  return { first: () => ({ json: FIXTURE.nodes[name] }), all: () => [{ json: FIXTURE.nodes[name] }] };
};
const INPUTS = {
  'QA Stage 1 Research': FIXTURE.nodes['Merge: Factory Profiles'],
  'QA Stage 2 Idea': FIXTURE.nodes['Parse Idea JSON'],
  'QA Stage 3 Design': FIXTURE.agent_reply,
  'QA Stage 4 Content': FIXTURE.agent_reply,
  'Parse QA Report': FIXTURE.agent_reply,
  'QA Stage 5 Export': FIXTURE.exported,
};
const inputJson = INPUTS[GATE];
const $input = { first: () => ({ json: inputJson }), all: () => [{ json: inputJson }] };
const $env = {};

const run = new Function('$', '$input', '$env', 'return (async () => {' + NODE_JS + '})();');
run($, $input, $env).then((out) => {
  const raw = out[0].json;
  // Stage 5 nests its verdict under export_qa and the marketplace stage under
  // qa; reading the top level made both look unconditionally clean.
  const j = raw.export_qa || raw.qa || raw;
  console.log(JSON.stringify({
    gate: GATE,
    passed: j.passed !== false,
    blockers: j.blockers || [],
    warnings: (j.warnings || []).slice(0, 4),
    score: j.score ?? null,
  }));
}).catch((e) => {
  console.log(JSON.stringify({ gate: GATE, crashed: String(e.message).slice(0, 200) }));
});
"""


SABOTAGE = {
    "duplicate page": lambda d: d["nodes"]["Parse Content JSON"]["content"]["pages"]
        .__setitem__(2, dict(d["nodes"]["Parse Content JSON"]["content"]["pages"][1])),
    "drafting marker": lambda d: d["nodes"]["Parse Content JSON"]["content"]["pages"][1]
        .__setitem__("lines", ["TODO: write this page"]),
    "empty page": lambda d: d["nodes"]["Parse Content JSON"]["content"]["pages"][1]
        .__setitem__("lines", []),
    "missing promised format": lambda d: d["exported"]["files"].pop(0),
    "corrupt pdf": lambda d: d["exported"]["files"][0].__setitem__("b64", "bm90IGEgcGRmIGF0IGFsbA=="),
}


def run_gate(tmp: str, code_of: dict, gate: str, data: dict) -> dict:
    script = os.path.join(tmp, "gate.js")
    with open(script, "w", encoding="utf-8") as fh:
        fh.write(HARNESS % (json.dumps(data), json.dumps(code_of[gate]), json.dumps(gate)))
    result = subprocess.run(["node", script], capture_output=True, text=True)
    if result.returncode != 0:
        return {"crashed": result.stderr.strip().splitlines()[-1][:160]}
    return json.loads(result.stdout.strip().splitlines()[-1])


def negative_checks(tmp: str, code_of: dict) -> int:
    """A gate that never blocks anything is not a gate.

    Every relaxation in this file was made because a rule fired on sound work.
    These put real defects in front of the same rules and require them to fire,
    so "stopped rejecting good products" cannot quietly become "stopped
    rejecting anything".
    """
    print("\n=== negative checks: real defects must still be caught ===")
    factory = next(f for f in FACTORIES if f["factory_key"] == "resume")
    gate_for = {
        "duplicate page": "QA Stage 4 Content",
        "drafting marker": "QA Stage 4 Content",
        "empty page": "QA Stage 4 Content",
        "missing promised format": "QA Stage 5 Export",
        "corrupt pdf": "QA Stage 5 Export",
    }
    failures = 0
    for label, break_it in SABOTAGE.items():
        data = fixture(factory)
        break_it(data)
        report = run_gate(tmp, code_of, gate_for[label], data)
        caught = bool(report.get("blockers")) or report.get("passed") is False
        print(f"  [{'ok  ' if caught else 'MISS'}] {label:24s} "
              f"{'; '.join(report.get('blockers', []))[:70] or report.get('crashed', '')}")
        if not caught:
            failures += 1
    return failures


SHAPES = {
    "array (the contract)": ["resume template", "cv kit"],
    "comma-joined string": "resume template, cv kit, job search",
    "object of values": {"a": "resume template", "b": "cv kit"},
    "one bare string": "resume template",
    "absent": None,
    "a number": 7,
    "nested object of arrays": {"primary": ["resume template"], "secondary": ["cv kit"]},
}


def shape_checks(tmp: str, code_of: dict) -> int:
    """A field the contract calls a list can arrive as anything.

    `x || []` only catches null, so a model answering with an object put
    "(tagsOut.tags || []) is not iterable" in front of a paid run. asArray
    interprets the answer instead of discarding it; these prove it holds for
    every shape seen so far, and that the content survives the coercion.
    """
    print("\n=== shape checks: a list field arriving as something else ===")
    factory = next(f for f in FACTORIES if f["factory_key"] == "resume")
    agent_nodes = ["OpenAI: SEO AI Title", "OpenAI: SEO AI Description",
                   "OpenAI: SEO AI Etsy Tags"]
    failures = 0
    for label, tags in SHAPES.items():
        data = fixture(factory)
        data["agent_reply"] = {"choices": [{"finish_reason": "stop", "message": {
            "content": json.dumps({"title": "Printable Resume Template",
                                   "description": "A calm kit.", "tags": tags,
                                   "materials": ["digital file"]})}}]}
        harness = HARNESS % (json.dumps(data),
                             json.dumps(code_of["Validate SEO Package"]),
                             json.dumps("Validate SEO Package"))
        harness = harness.replace(
            "const $ = (name) => {",
            f"const AGENT_NODES = {json.dumps(agent_nodes)};\n"
            "const $ = (name) => {\n"
            "  if (AGENT_NODES.includes(name)) return { first: () => ({ json: FIXTURE.agent_reply }) };")
        harness = harness.replace("const INPUTS = {",
                                  "const INPUTS = {\n  'Validate SEO Package': FIXTURE.agent_reply,")
        harness = harness.replace("  const j = raw.export_qa || raw.qa || raw;",
                                  "  const j = raw.seo || raw;")
        harness = harness.replace("    blockers: j.blockers || [],",
                                  "    blockers: [], tags: (j.tags || []).length,")
        script = os.path.join(tmp, "shape.js")
        with open(script, "w", encoding="utf-8") as fh:
            fh.write(harness)
        result = subprocess.run(["node", script], capture_output=True, text=True)
        report = ({} if result.returncode else
                  json.loads(result.stdout.strip().splitlines()[-1]))
        if result.returncode or report.get("crashed") or report.get("tags") != 13:
            detail = report.get("crashed") or result.stderr.strip().splitlines()[-1][:70]
            print(f"  [FAIL] tags as {label:24s} {detail}")
            failures += 1
        else:
            print(f"  [ok  ] tags as {label:24s} -> 13 Etsy tags")
    return failures


def provider_checks(tmp: str) -> int:
    """The parsers must read either provider's reply shape.

    A build can target OpenAI or Gemini, and their responses agree on nothing:
    choices[].message.content versus candidates[].content.parts[].text, usage
    versus usageMetadata, finish_reason versus finishReason. One reader covers
    both; these drive it with a real example of each.
    """
    print("\n=== provider checks: one reader, two reply shapes ===")
    from common import AGENT_CONTENT_JS
    payload = '{"product_name":"The Clear Start Resume Kit","sections":[{"title":"Cover"}]}'
    cases = {
        "openai": {"choices": [{"finish_reason": "stop",
                                "message": {"content": payload}}],
                   "usage": {"prompt_tokens": 312, "completion_tokens": 70}},
        "gemini": {"candidates": [{"finishReason": "STOP",
                                   "content": {"parts": [{"text": payload}]}}],
                   "usageMetadata": {"promptTokenCount": 312,
                                     "candidatesTokenCount": 70,
                                     "totalTokenCount": 382}},
        "gemini split across parts": {
            "candidates": [{"finishReason": "STOP", "content": {"parts": [
                {"text": payload[:40]}, {"text": payload[40:]}]}}],
            "usageMetadata": {"promptTokenCount": 5, "candidatesTokenCount": 5}},
        "gemini truncated": {
            "candidates": [{"finishReason": "MAX_TOKENS",
                            "content": {"parts": [{"text": '{"a":'}]}}]},
    }
    script = os.path.join(tmp, "provider.js")
    failures = 0
    for label, response in cases.items():
        harness = AGENT_CONTENT_JS + f"""
const r = {json.dumps(response)};
const content = agentContent(r);
const usage = agentUsage(r);
const finish = agentFinish(r);
let name = null;
try {{ name = JSON.parse(content).product_name; }} catch (e) {{ name = 'UNPARSEABLE'; }}
console.log(JSON.stringify({{ finish, prompt: usage && usage.prompt_tokens,
                              completion: usage && usage.completion_tokens, name }}));
"""
        with open(script, "w", encoding="utf-8") as fh:
            fh.write(harness)
        result = subprocess.run(["node", script], capture_output=True, text=True)
        if result.returncode:
            print(f"  [FAIL] {label:26s} {result.stderr.strip().splitlines()[-1][:60]}")
            failures += 1
            continue
        out = json.loads(result.stdout.strip().splitlines()[-1])
        want_truncated = "truncated" in label
        ok = (out["finish"] == ("max_tokens" if want_truncated else "stop")
              and (out["name"] == "UNPARSEABLE" if want_truncated
                   else out["name"] == "The Clear Start Resume Kit"))
        print(f"  [{'ok  ' if ok else 'FAIL'}] {label:26s} finish={out['finish']:10s} "
              f"tokens={out['prompt']}/{out['completion']} name={out['name']}")
        failures += 0 if ok else 1
    return failures


TAG_INPUTS = ["tech leadership resume", "ATS-Friendly Resume!", "cafe planner printable",
              "resume template", "supercalifragilisticexpialidocious", "cv",
              "printable resume for job seekers"]


def tag_checks(tmp: str, code_of: dict) -> int:
    """No Etsy tag may be cut mid-word.

    The cap is 20 characters and it used to be applied with a plain slice, so a
    listing shipped the tag 'tech leadership resu'. QA caught it as a spelling
    error - correctly - after the run had already paid for its images.
    """
    print("\n=== tag checks: Etsy's 20-character cap ===")
    js = code_of["Validate SEO Package"]
    frag = js[js.index("const normaliseTag"):js.index("const candidates")]
    script = os.path.join(tmp, "tags.js")
    with open(script, "w", encoding="utf-8") as fh:
        fh.write(frag + f"""
const cases = {json.dumps(TAG_INPUTS)};
console.log(JSON.stringify(cases.map((c) => [c, normaliseTag(c)])));
""")
    result = subprocess.run(["node", script], capture_output=True, text=True)
    if result.returncode:
        print("  [FAIL] harness crashed:", result.stderr.strip().splitlines()[-1][:70])
        return 1
    failures = 0
    for source, tag in json.loads(result.stdout.strip().splitlines()[-1]):
        clean = re.sub(r"[^a-z0-9 ]", " ", source.lower())
        words = set(clean.split())
        cut = bool(tag) and (len(tag) > 20 or any(w not in words for w in tag.split()))
        if cut:
            print(f"  [FAIL] {source!r} -> {tag!r}")
            failures += 1
        else:
            print(f"  [ok  ] {(tag or '(dropped)'):22s} {len(tag):2d}  <- {source}")
    return failures


def main() -> int:
    with open(os.path.join(ROOT, "workflows", "03_product_engine.json"),
              encoding="utf-8") as fh:
        document = json.load(fh)
    code_of = {n["name"]: n["parameters"].get("jsCode", "") for n in document["nodes"]}

    wanted = sys.argv[1:] or [f["factory_key"] for f in FACTORIES]
    failures = 0

    with tempfile.TemporaryDirectory() as tmp:
        for factory in FACTORIES:
            if factory["factory_key"] not in wanted:
                continue
            data = fixture(factory)
            print(f"\n=== {factory['factory_key']} "
                  f"({factory['target_pages']} pages, {factory['image_pages']} art, "
                  f"svg={factory['svg_required']}) ===")
            for gate in GATES:
                script = os.path.join(tmp, "gate.js")
                with open(script, "w", encoding="utf-8") as fh:
                    fh.write(HARNESS % (json.dumps(data), json.dumps(code_of[gate]),
                                        json.dumps(gate)))
                result = subprocess.run(["node", script], capture_output=True, text=True)
                if result.returncode != 0:
                    print(f"  [ERR ] {gate}: {result.stderr.strip().splitlines()[-1][:120]}")
                    failures += 1
                    continue
                report = json.loads(result.stdout.strip().splitlines()[-1])
                if report.get("crashed"):
                    print(f"  [CRASH] {gate}: {report['crashed']}")
                    failures += 1
                elif report["passed"] and not report["blockers"]:
                    warn = f"  ({len(report['warnings'])} warning(s))" if report["warnings"] else ""
                    print(f"  [pass] {gate:22s} score={report['score']}{warn}")
                else:
                    print(f"  [FAIL] {gate:22s} {'; '.join(report['blockers']) or 'passed=false'}")
                    failures += 1

        failures += negative_checks(tmp, code_of)
        failures += shape_checks(tmp, code_of)
        failures += provider_checks(tmp)
        failures += tag_checks(tmp, code_of)

    print()
    if failures:
        print(f"{failures} gate failure(s) - a real run would be rejected")
        return 1
    print("every gate passes for every factory on a realistic run")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
